import sys
sys.setrecursionlimit(1000)
memo = {}

def n_ways(v, max_c):
	if (v, max_c) in memo:
		return memo[v, max_c]
	if v == 0:
		return 1
	if v < min(C):
		return 0
	sum = 0
	for each in C:
		if each <= max_c:
			sum += n_ways(v - each, each)
	memo[v, max_c] = sum
	return sum
N = list(map(int, input().split(' ')))[0]
C = list(map(int, input().rstrip(' ').split(' ')))
print(n_ways(N, max(C)))
